# route table: one entry per page
route('/orders', orders_page)      # GET  -> form
route('/orders', orders_submit)    # POST -> action

def orders_page(req):
    require_login(req)                      # shared check, called explicitly
    return render('orders.html', list_orders(req.user))

def orders_submit(req):
    order = parse_order(req.form)           # request handling
    place_order(order)                      # domain logic
    redirect('/orders')                     # POST-redirect-GET
